class Solution:
    def minimumSemesters(self, n: int, relations: list[list[int]]) -> int:
        pre = [set() for _ in range(n + 1)]
        for a, b in relations:
            pre[b].add(a)
        done = set()
        semesters = 0
        while len(done) < n:
            take = [c for c in range(1, n + 1) if c not in done and pre[c] <= done]
            if not take:
                return -1
            done.update(take)
            semesters += 1
        return semesters

