class Solution:
    def minimumSemesters(self, n: int, relations: list[list[int]]) -> int:
        g = [[] for _ in range(n + 1)]
        for a, b in relations:
            g[a].append(b)
        color = [0] * (n + 1)
        memo = [0] * (n + 1)
        def dfs(u):
            if color[u] == 1:
                return -1
            if color[u] == 2:
                return memo[u]
            color[u] = 1
            best = 1
            for v in g[u]:
                got = dfs(v)
                if got == -1:
                    return -1
                best = max(best, got + 1)
            color[u] = 2; memo[u] = best
            return best
        ans = 0
        for i in range(1, n + 1):
            got = dfs(i)
            if got == -1:
                return -1
            ans = max(ans, got)
        return ans

